protected void processJournalTransaction(Set _rebateDates, Common _journalTransaction, Map _accountCodes)
{
    next processJournalTransaction(_rebateDates, _journalTransaction, _accountCodes);

    //this.checkGUPMatchedRebateDatesV2(_rebateDates, _journalTransaction);
}

/// <summary>
/// CB_705
/// </summary>
/// <param name = "_rebateDates"></param>
/// <param name = "_journalTransaction"></param>
internal void METcheckMatchedRebateDatesV2(Set _rebateDates, Common _journalTransaction)
{
    Set matchedRebateDates = new Set(Types::Int64);

    if (!_rebateDates.empty() && rebateModule == ModuleInventCustVend::Vend)
    {

        if (_journalTransaction is CustInvoiceTrans)
        {
            GUPPropertyHashTmp orderAttributeValueHeaderHash;
            GUPPricingOfferTmp rebateDateRecIds;
            GUPRuleHash headerRuleHash;
            CustInvoiceTrans custInvoiceTrans = _journalTransaction as CustInvoiceTrans;
            SalesTable  salesTable = METRebateMatchingHelper::metInitSalesTableFromCustInvoiceJour(CustInvoiceJour::findRecId(custInvoiceTrans.ParentRecId));
            salesTable.RecId = -1;
            this.metInsertTmpTable(_rebateDates, rebateDateRecIds, false, tableNum(GUPPricingOfferTmp), fieldNum(GUPPricingOfferTmp, PricingOfferRecId));
            Set headerHashKeySet = METHashHelper::getPropertyHashKeySetForPricingObject(salesTable, GUPPricingAttributeSourceLevel::Header);
            this.metInsertTmpTable(headerHashKeySet, orderAttributeValueHeaderHash, true, tableNum(GUPPropertyHashTmp), fieldNum(GUPPropertyHashTmp, HashValue));
            TAMRebateTable rebateTable;
            TAMRebateDate rebateDate;
            GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

            while select RecId from rebateDate
                join RebateId, PriceComponentCombination from rebateTable
                    where rebateTable.RebateId == rebateDate.RebateId
                outer join LineGroupAll from groupCombination
                    where groupCombination.RecId == rebateTable.PriceComponentCombination
                exists join rebateDateRecIds
                    where rebateDate.RecId == rebateDateRecIds.PricingOfferRecId
                exists join headerRuleHash
                    where rebateTable.PricingRuleHeader== headerRuleHash.RuleId
                exists join orderAttributeValueHeaderHash
                    where orderAttributeValueHeaderHash.HashValue == headerRuleHash.HashValue
            {
                if ((rebateTable.PriceComponentCombination == 0 || groupCombination.LineGroupAll == GUPGroupAll::All)
                    && !METHashHelper::checkRuleMatchedWithExclusion(rebatetable.PricingRuleHeader, salesTable))
                {
                    matchedRebateDates.add(rebateDate.RecId);
                }
            }
        }
        else
        {

            str tableName = tableId2Name(rebateQueryBuilder.transTable());
            PurchTable purchTable = PurchTable::find(_journalTransaction.(fieldName2Id(tableName2Id(tableName), 'PurchId')));

            if (purchTable.RecId)
            {
                GUPPropertyHashTmp orderAttributeValueHeaderHash, orderAttributeValueLineHash;
                GUPPricingOfferTmp rebateDateRecIds;
                GUPRuleHash headerRuleHash, lineRuleHash;
                PurchLine purchLine = _journalTransaction is PurchLine ?
                                      _journalTransaction as PurchLine :
                                      PurchLine::findInventTransId(_journalTransaction.(fieldName2Id(tableName2Id(tableName), 'InventTransId')));

                if (purchLine.lineAmount == 0)
                {
                    this.metCleanSet(_rebateDates, matchedRebateDates);
                    return;
                }

                this.metInsertTmpTable(_rebateDates, rebateDateRecIds, false, tableNum(GUPPricingOfferTmp), fieldNum(GUPPricingOfferTmp, PricingOfferRecId));
                Set lineHashKeySet = METHashHelper::getPropertyHashKeySetForPricingObject(purchLine, GUPPricingAttributeSourceLevel::Line);
                this.metInsertTmpTable(lineHashKeySet, orderAttributeValueLineHash, true, tableNum(GUPPropertyHashTmp), fieldNum(GUPPropertyHashTmp, HashValue));
                boolean enablePriceTree = GUPParameters::find().EnablePriceTree;
                Set componentCodeNames = enablePriceTree ? GUPPricingTree::METGetComponentCodeNamesLinkedWithPriceTreeFromPurchId(purchTable.PurchId) : new Set(Types::String);
                TAMRebateTable rebateTable;
                TAMRebateDate rebateDate;
                GUPPriceComponentCodePriceAttributeGroupCombination groupCombination;

                while select RecId from rebateDate
                    join RebateId, PricingRuleHeader, PricingRuleLine, PriceComponentCombination from rebateTable
                        where rebateTable.RebateId == rebateDate.RebateId
                    outer join PriceComponentCodeName from groupCombination
                        where groupCombination.RecId == rebateTable.PriceComponentCombination
                    exists join rebateDateRecIds
                        where rebateDate.RecId == rebateDateRecIds.PricingOfferRecId
                    exists join lineRuleHash
                        where rebateTable.PricingRuleLine == lineRuleHash.RuleId
                    exists join orderAttributeValueLineHash
                        where orderAttributeValueLineHash.HashValue == lineRuleHash.HashValue
                {
                    if (!METHashHelper::checkRuleMatchedWithExclusion(rebatetable.PricingRuleLine, purchLine))
                    {
                        if (rebateTable.PriceComponentCombination && enablePriceTree)
                        {
                            if (componentCodeNames.in(groupCombination.PriceComponentCodeName))
                            {
                                matchedRebateDates.add(rebateDate.RecId);
                            }
                        }
                        else
                        {
                            matchedRebateDates.add(rebateDate.RecId);
                        }
                    }
                }
            }
        }


        this.METCleanSet(_rebateDates, matchedRebateDates);

    }

}

/// <summary>
/// CB_705
/// </summary>
/// <param name = "_rebateDates"></param>
/// <param name = "_matchedRebateDates"></param>
void METCleanSet(Set _rebateDates, Set _matchedRebateDates)
{
    Set cloneSet = Set::create(_rebateDates.pack());
    SetEnumerator setEnumerator = cloneSet.getEnumerator();
    while (setEnumerator.moveNext())
    {
        if (!_matchedRebateDates.in(setEnumerator.current()))
        {
            _rebateDates.remove(setEnumerator.current());
        }
    }
}

internal void metinsertTmpTable(
    Set _valueSet,
    Common _tmpRecord,
    boolean _calculateHash = true,
    TableId _tableId = tableNum(GUPPropertyHashTmp),
    FieldId _fieldId = fieldNum(GUPPropertyHashTmp, HashValue))
{
    RecordInsertList recordInsertList = new RecordInsertList(_tableId, false, false, false, false, true, _tmpRecord);
    SetEnumerator setEnumerator = _valueSet.getEnumerator();
    while (setEnumerator.moveNext())
    {
        _tmpRecord.clear();
        _tmpRecord.(_fieldId) = _calculateHash ? METHashHelper::HashValue(setEnumerator.current()) : setEnumerator.current();
        recordInsertList.add(_tmpRecord);
    }
    recordInsertList.insertDatabase();
}
